"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

export default function TaskItem({ id, columnId, text, onDelete, onEdit }: any) {
  const { setNodeRef, attributes, listeners, transform, transition } = useSortable({
    id,
    data: { column: columnId },
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="p-3 bg-gray-800 text-white rounded-lg shadow hover:scale-[1.02] transition cursor-grab flex justify-between items-center"
    >
      <span>{text}</span>
      <div className="flex gap-2">
        <button onClick={() => onEdit(id)} className="text-blue-500 hover:text-blue-400">
          ✏️
        </button>
        <button onClick={() => onDelete(id)} className="text-red-500 hover:text-red-400">
          🗑️
        </button>
      </div>
    </div>
  );
}