"use client";

import { useState, useEffect } from "react";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import TaskItem from "./TaskItem";
import { v4 as uuid } from "uuid";

export default function ScrumColumn({ id, title, items, setColumns, currentUser }: any) {
  const [showForm, setShowForm] = useState(false);
  const [input, setInput] = useState("");

  // Guest için local state, user için API çağrısı
  const addTask = async () => {
    if (!input.trim()) return;
    const newTask = { id: uuid(), title: input };

    setColumns((prev: any) => ({
      ...prev,
      [id]: [...prev[id], newTask],
    }));

    setInput("");
    setShowForm(false);

    // Eğer user varsa DB kaydı yap
    if (currentUser) {
      await fetch("/api/tasks", {
        method: "POST",
        body: JSON.stringify({ title: newTask.title, status: id }),
        headers: { "Content-Type": "application/json" },
      });
    }
  };

  const deleteTask = (taskId: string) => {
    setColumns((prev: any) => ({
      ...prev,
      [id]: prev[id].filter((t: any) => t.id !== taskId),
    }));
  };

  const editTask = (taskId: string) => {
    const newTitle = prompt("Nieuwe titel:", items.find((t: any) => t.id === taskId)?.title);
    if (!newTitle) return;
    setColumns((prev: any) => ({
      ...prev,
      [id]: prev[id].map((t: any) => (t.id === taskId ? { ...t, title: newTitle } : t)),
    }));
  };

  return (
    <>
      <div className="bg-gray-900/70 backdrop-blur-lg p-4 rounded-xl shadow-lg w-[280px] border border-gray-700">
        <h2 className="text-lg font-semibold mb-4 text-white">{title}</h2>

        <SortableContext items={items.map((i: any) => i.id)} strategy={verticalListSortingStrategy}>
          <div className="flex flex-col gap-3 min-h-[50px]">
            {items.map((item: any) => (
              <TaskItem
                key={item.id}
                id={item.id}
                columnId={id}
                text={item.title}
                onDelete={deleteTask}
                onEdit={editTask}
              />
            ))}
          </div>
        </SortableContext>

        <button
          onClick={() => setShowForm(true)}
          className="w-full mt-4 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-700 transition"
        >
          + Taak toevoegen
        </button>
      </div>

      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setShowForm(false)} />
          <div className="relative z-10 w-full max-w-md rounded-2xl bg-gray-900/95 backdrop-blur-xl shadow-2xl border border-gray-700 p-6 text-white">
            <h3 className="text-xl font-semibold mb-2">✨ Nieuwe taak</h3>
            <textarea
              className="w-full h-28 p-3 rounded-xl border border-gray-700 bg-gray-800 text-white focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              placeholder="Bijv: Login systeem bouwen..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  addTask();
                }
              }}
              autoFocus
            />

            <div className="flex justify-end gap-3 mt-5">
              <button onClick={() => setShowForm(false)} className="px-4 py-2 rounded-lg text-gray-300 hover:bg-gray-800 transition">
                Annuleren
              </button>
              <button
                onClick={addTask}
                disabled={!input.trim()}
                className="px-5 py-2 rounded-lg bg-blue-600 text-white font-medium hover:bg-blue-700 disabled:opacity-50 transition shadow-md"
              >
                Toevoegen
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}