"use client";

import { useState } from "react";
import { DndContext, closestCenter, DragEndEvent } from "@dnd-kit/core";
import { arrayMove, SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import ScrumColumn from "./ScrumColumn";

export default function ScrumBoard() {
  const [columns, setColumns] = useState({
    backlog: [],
    sprint: [],
    todo: [],
    progress: [],
    done: [],
  });

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const fromCol = active.data.current?.column;
    const toCol = over.data.current?.column;
    const taskId = active.id;

    if (!fromCol || !toCol) return;

    if (fromCol === toCol) {
      const oldTasks = columns[fromCol];
      const oldIndex = oldTasks.findIndex((t: any) => t.id === taskId);
      const newIndex = oldTasks.findIndex((t: any) => t.id === over.id);

      const newTasks = arrayMove(oldTasks, oldIndex, newIndex);
      setColumns({ ...columns, [fromCol]: newTasks });
    } else {
      // Farklı kolona taşımak
      const fromTasks = [...columns[fromCol]];
      const task = fromTasks.find((t: any) => t.id === taskId);
      if (!task) return;
      const toTasks = [...columns[toCol], task];
      setColumns({
        ...columns,
        [fromCol]: fromTasks.filter((t: any) => t.id !== taskId),
        [toCol]: toTasks,
      });
    }
  };

  return (
    <DndContext collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <div className="flex gap-6 overflow-x-auto">
        {["backlog", "sprint", "todo", "progress", "done"].map((colId) => (
          <ScrumColumn
            key={colId}
            id={colId}
            title={{
              backlog: "📋 Backlog",
              sprint: "📝 Sprint Backlog",
              todo: "🟡 To Do",
              progress: "🔵 In Progress",
              done: "✅ Done",
            }[colId]}
            items={columns[colId]}
            setColumns={setColumns}
          />
        ))}
      </div>
    </DndContext>
  );
}